$insL = $pdo->prepare("INSERT INTO lecciones (curso_id, titulo, descripcion, video_url, orden) VALUES (?, ?, ?, ?, ?)");
$insA = $pdo->prepare("INSERT INTO actividades (leccion_id, titulo, descripcion, tipo) VALUES (?, ?, ?, 'responder_texto')");

$totalL = 0; $totalA = 0;

foreach ($data as $w) {
    $base = $w['semana'] * 10;
    $insL->execute([$cursoId, "Clase {$w['semana']}: {$w['titulo_semana']} — {$w['clase_maestra']['titulo']}", $w['clase_maestra']['desc'], null, $base + 1]);
    $id = $pdo->lastInsertId(); $totalL++;
    if ($w['quest']) { $insA->execute([$id, $w['quest']['titulo'], $w['quest']['desc']]); $totalA++; }
    foreach ($w['mini'] as $i => $m) {
        $miniTitulo = preg_replace('/^Mini \d+:\s*/', '', $m['titulo']);
        $numSub = $i + 1;
        $insL->execute([$cursoId, "Clase {$w['semana']}.{$numSub}: {$miniTitulo}", $m['desc'], null, $base + 2 + $i]);
        $mid = $pdo->lastInsertId(); $totalL++;
        if ($m['act']) { $insA->execute([$mid, $m['act']['titulo'], $m['act']['desc']]); $totalA++; }
    }
}

echo "OK: $totalL lecciones, $totalA actividades" . PHP_EOL;
